def semantic_validation_reference() -> str:
    """Name the repository-only semantic validation reference."""

    return "protocol.reference.validate (repository conformance only)"


def parse_action(value: JSONValue) -> ActionRequest:
    """Parse and structurally validate action JSON.

    Semantic validation remains separate.
    """

    document = _validate_document("action", value)
    return ActionRequest._from_dict(document)


def parse_action_json(document: bytes | str) -> ActionRequest:
    """Strictly parse action wire JSON before validation."""

    return parse_action(_strict_loads_json(document))


def parse_decision(value: JSONValue) -> AuthorizationDecision:
    """Parse and structurally validate decision JSON.

    Semantic validation remains separate.
    """

    document = _validate_document("decision", value)
    return AuthorizationDecision._from_dict(document)


def parse_decision_json(document: bytes | str) -> AuthorizationDecision:
    """Strictly parse decision wire JSON before validation."""

    return parse_decision(_strict_loads_json(document))


def parse_approval(value: JSONValue) -> ApprovalRecord:
    """Parse and structurally validate approval JSON.

    Semantic validation remains separate.
    """

    document = _validate_document("approval", value)
    return ApprovalRecord._from_dict(document)


